import{_ as t,o as i,c as a,ao as n}from"./chunks/framework.ucUddl5u.js";const h=JSON.parse('{"title":"Ship of Tools — an Agentic Julia Development Environment — Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"design/requirements.md","filePath":"design/requirements.md","lastUpdated":null}'),o={name:"design/requirements.md"};function r(s,e,l,u,p,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="Ship-of-Tools-—-an-Agentic-Julia-Development-Environment-—-Requirements" tabindex="-1">Ship of Tools — an Agentic Julia Development Environment — Requirements <a class="header-anchor" href="#Ship-of-Tools-—-an-Agentic-Julia-Development-Environment-—-Requirements" aria-label="Permalink to &quot;Ship of Tools — an Agentic Julia Development Environment — Requirements {#Ship-of-Tools-—-an-Agentic-Julia-Development-Environment-—-Requirements}&quot;">​</a></h1><p><em>Draft v0.1 — problem and requirements only. Implementation choices are deliberately deferred.</em></p><h2 id="Problem" tabindex="-1">Problem <a class="header-anchor" href="#Problem" aria-label="Permalink to &quot;Problem {#Problem}&quot;">​</a></h2><p>Working with a Julia codebase — whether you wrote it yourself, an LLM wrote it, or you have just landed in someone else&#39;s repo — the developer&#39;s bottleneck is <strong>comprehension</strong>, not text manipulation. Conventional IDEs surface files and lines well but expose structure, types, runtime outputs, and the underlying math poorly. This hurts onboarding, code review, and debugging in any context, and is especially acute in LLM-assisted development, where the human never builds understanding line by line.</p><h2 id="Goal" tabindex="-1">Goal <a class="header-anchor" href="#Goal" aria-label="Permalink to &quot;Goal {#Goal}&quot;">​</a></h2><p>A keyboard-driven Julia development environment built to be driven by AI agents: the agents write, run, and surface code while the developer steers, watches, and reviews. It preserves the conventional mechanics of finding, viewing, editing, and running any <code>.jl</code> file with a persistent REPL, and layers a <strong>concept explorer</strong> on top — letting a developer move fluidly between levels of abstraction (project, module, type, function, outputs, math). The LLM has a dual role: it writes and edits code, and it maintains the concept-explorer artifacts so they stay in sync with the codebase as it evolves.</p><h2 id="Users-and-scope" tabindex="-1">Users and scope <a class="header-anchor" href="#Users-and-scope" aria-label="Permalink to &quot;Users and scope {#Users-and-scope}&quot;">​</a></h2><ul><li><p>Single user.</p></li><li><p>One project at a time. A project is flexible in definition but is typically a git repository.</p></li><li><p>Cross-platform: must run on Windows and Linux.</p></li><li><p>Local and remote operation are both supported, and must offer the same user experience.</p></li></ul><h2 id="Functional-requirements" tabindex="-1">Functional requirements <a class="header-anchor" href="#Functional-requirements" aria-label="Permalink to &quot;Functional requirements {#Functional-requirements}&quot;">​</a></h2><h3 id="Code-authoring-and-execution" tabindex="-1">Code authoring and execution <a class="header-anchor" href="#Code-authoring-and-execution" aria-label="Permalink to &quot;Code authoring and execution {#Code-authoring-and-execution}&quot;">​</a></h3><ul><li><p>The LLM is the primary author of code. The user may also edit code directly.</p></li><li><p>The user must be able to find, view, edit, and run any <code>.jl</code> file in the project using only the keyboard.</p></li><li><p>The user must be able to dispatch code to the REPL at multiple granularities.</p></li><li><p>A persistent Julia REPL must be available throughout a session.</p></li></ul><h3 id="Document-authoring" tabindex="-1">Document authoring <a class="header-anchor" href="#Document-authoring" aria-label="Permalink to &quot;Document authoring {#Document-authoring}&quot;">​</a></h3><ul><li>The user must be able to author markdown documents (such as PRDs) directly in the environment.</li></ul><h3 id="File-navigation-and-inspection" tabindex="-1">File navigation and inspection <a class="header-anchor" href="#File-navigation-and-inspection" aria-label="Permalink to &quot;File navigation and inspection {#File-navigation-and-inspection}&quot;">​</a></h3><ul><li><p>The user must be able to navigate the entire project filesystem by keyboard alone.</p></li><li><p>The environment must render previews of project files at appropriate fidelity for their type, beginning with PNG images, and including markdown, MP4 video, and JSON. Other figure and structured-data formats are within scope and may be added incrementally.</p></li><li><p>The user must be able to pin a file to a persistent view that updates as the file changes on disk.</p></li></ul><h3 id="Concept-explorer" tabindex="-1">Concept explorer <a class="header-anchor" href="#Concept-explorer" aria-label="Permalink to &quot;Concept explorer {#Concept-explorer}&quot;">​</a></h3><ul><li><p>The system must support inspection of, at a minimum: source code, type structure, program outputs, project and module structure, and mathematical content.</p></li><li><p>The LLM must maintain — and keep current with the codebase — artifacts capturing project intent, module purpose, type meaning, function contracts, mathematical derivations, and data shapes.</p></li><li><p>The user must be able to move between levels of abstraction, from project overview down to specifics, without leaving the environment.</p></li><li><p>When a project has no existing concept-explorer artifacts (for example, when first opening an unfamiliar repo), generating them is the LLM&#39;s responsibility.</p></li></ul><h3 id="Multi-agent-operation" tabindex="-1">Multi-agent operation <a class="header-anchor" href="#Multi-agent-operation" aria-label="Permalink to &quot;Multi-agent operation {#Multi-agent-operation}&quot;">​</a></h3><ul><li><p>Multiple LLM agents must be able to work on the project simultaneously without interfering with each other&#39;s in-progress changes.</p></li><li><p>The user must be able to start, pause, resume, and stop agents.</p></li><li><p>The user must always be able to see what each active agent is doing and what state it is in.</p></li><li><p>The user must be able to inspect, after the fact, any agent&#39;s actions, reasoning, and outputs in enough detail to verify the work.</p></li><li><p>The user must be able to compare, accept, or discard each agent&#39;s work product.</p></li></ul><h3 id="LLM-mediation-and-control" tabindex="-1">LLM mediation and control <a class="header-anchor" href="#LLM-mediation-and-control" aria-label="Permalink to &quot;LLM mediation and control {#LLM-mediation-and-control}&quot;">​</a></h3><ul><li><p>The LLM is the user&#39;s primary means of operating the environment beyond core editor and REPL interactions.</p></li><li><p>Decisions about which actions require user confirmation are the LLM&#39;s responsibility. The environment does not impose its own permission tiers, sandboxes, or rule-based action gating.</p></li></ul><h3 id="Window-and-layout-management" tabindex="-1">Window and layout management <a class="header-anchor" href="#Window-and-layout-management" aria-label="Permalink to &quot;Window and layout management {#Window-and-layout-management}&quot;">​</a></h3><ul><li><p>The layout system must accommodate both ultrawide displays and small laptop displays (16:10) without per-device reconfiguration by the user.</p></li><li><p>All layout operations must be possible from the keyboard.</p></li></ul><h2 id="Quality-requirements" tabindex="-1">Quality requirements <a class="header-anchor" href="#Quality-requirements" aria-label="Permalink to &quot;Quality requirements {#Quality-requirements}&quot;">​</a></h2><h3 id="Reliability" tabindex="-1">Reliability <a class="header-anchor" href="#Reliability" aria-label="Permalink to &quot;Reliability {#Reliability}&quot;">​</a></h3><ul><li><p>File navigation, content inspection, the editor, the REPL, and watch views must continue to function when the LLM service is unavailable.</p></li><li><p>All static content — anything written to disk in the project — must survive a restart of the environment. In-memory state (REPL bindings, agent conversations, live processes) is not required to persist.</p></li></ul><h3 id="Responsiveness" tabindex="-1">Responsiveness <a class="header-anchor" href="#Responsiveness" aria-label="Permalink to &quot;Responsiveness {#Responsiveness}&quot;">​</a></h3><ul><li><p>Interactive operations — navigation, opening files, dispatching code to the REPL, switching views — must feel immediate.</p></li><li><p>Long-running operations such as agent tasks may run in the background for arbitrary durations, including hours.</p></li></ul><h3 id="Remote-and-local-parity" tabindex="-1">Remote and local parity <a class="header-anchor" href="#Remote-and-local-parity" aria-label="Permalink to &quot;Remote and local parity {#Remote-and-local-parity}&quot;">​</a></h3><ul><li>The user experience on a remote project must be indistinguishable from a local project: same surfaces, same capabilities, same interaction feel.</li></ul><h3 id="Future-proofing" tabindex="-1">Future-proofing <a class="header-anchor" href="#Future-proofing" aria-label="Permalink to &quot;Future-proofing {#Future-proofing}&quot;">​</a></h3><p>The system must avoid the following assumptions, all of which are expected to become limiting within the next year:</p><ul><li><p>A single LLM model or provider.</p></li><li><p>Short-running operations only.</p></li><li><p>Text-only inputs and outputs; visual artifacts must flow in both directions.</p></li><li><p>A fixed tool surface available to the LLM.</p></li><li><p>A single task or session active at a time.</p></li></ul><h2 id="Out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#Out-of-scope" aria-label="Permalink to &quot;Out of scope {#Out-of-scope}&quot;">​</a></h2><ul><li><p>Manual coding as the primary workflow. The LLM writes code; the user may intervene.</p></li><li><p>IDE features whose purpose is to support manual authoring of code: language servers, completion, linting, formatting, refactoring tooling, and graphical debuggers.</p></li><li><p>Mouse-driven interaction.</p></li><li><p>Multi-user or collaborative use of the environment.</p></li><li><p>First-class environment surfaces for runtime value inspection, dataflow visualization, and execution tracing. The user accesses runtime values through the REPL itself.</p></li><li><p>A configuration surface specified at the requirements level. Configuration will be opinionated by design and is treated as an implementation concern.</p></li></ul><h2 id="Deferred-to-implementation" tabindex="-1">Deferred to implementation <a class="header-anchor" href="#Deferred-to-implementation" aria-label="Permalink to &quot;Deferred to implementation {#Deferred-to-implementation}&quot;">​</a></h2><p>These were raised during requirements discussion and are intentionally not specified here:</p><ul><li><p>The format, location, and update discipline of concept-explorer artifacts.</p></li><li><p>The coordination model among parallel agents and the mechanism by which they are isolated.</p></li><li><p>The specific bridge between the LLM and the REPL — what it can read, inject, and inspect.</p></li><li><p>The window-management model that satisfies the layout requirements.</p></li><li><p>The transport and architecture of the local-and-remote-parity experience.</p></li><li><p>The configuration mechanism by which user preferences are expressed to the LLM.</p></li></ul><h2 id="Amendment-2026-07-05-—-distribution-is-in-scope-ADR-0030" tabindex="-1">Amendment 2026-07-05 — distribution is in scope (ADR 0030) <a class="header-anchor" href="#Amendment-2026-07-05-—-distribution-is-in-scope-ADR-0030" aria-label="Permalink to &quot;Amendment 2026-07-05 — distribution is in scope (ADR 0030) {#Amendment-2026-07-05-—-distribution-is-in-scope-ADR-0030}&quot;">​</a></h2><p>This document originally predated any distribution story; going public made one load-bearing. The following are now <strong>in scope</strong>, governed by ADR 0030 (and its clone-install amendment):</p><ul><li><p><strong>Public releases</strong>: versioned, tag-driven, prebuilt binaries for Linux and Windows (macOS experimental), CI-gated by artifact smoke tests, a Julia env resolve+load check, and a full-history secret scan.</p></li><li><p><strong>Installation</strong>: a scripted installer (interactive or flag-driven) laying down binaries plus a repo checkout pinned at the release tag — the checkout doubles as the product&#39;s resource tree and its in-app manual.</p></li><li><p><strong>Self-update</strong>: installed instances detect, download, verify, and stage new releases; apply is staged-next-launch with rollback.</p></li></ul><p>Unchanged: multi-user/collaborative use of one environment instance stays out of scope; &quot;distribution&quot; means many single-user installs, not a shared deployment.</p>',42)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
